window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["anki:obstetricia-vitalidade-fetal"]={"block":"anki:obstetricia-vitalidade-fetal","label":"Anki · Vitalidade Fetal","count":100,"questions":[{"id":"anki-obstetricia-vitalidade-fetal-0d9707d27db57825","number":"0301h","sourceNumber":"0301h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Pode-se afirmar que no sistema de interpretação da frequência cardíaca fetal (FCF) na cardiotocografia em três categorias, representa melhor a categoria 3:","options":{"A":"aceleração presente.","B":"desacelerações variáveis repetidas (> 50%).","C":"desaceleração precoce presente.","D":"variabilidade da FCF basal moderada."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784712","ankiGuid":"O`6I^SKK+_"},{"id":"anki-obstetricia-vitalidade-fetal-31e275b16dcde505","number":"0302h","sourceNumber":"0302h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Durante a condução de um trabalho de parto em uma gestante hipertensa, ao ser realizado exame cardiotocográfico, foram observadas desacelerações intraparto (DIP) do tipo II ou tardios. Esta alteração está relacionada a:","options":{"A":"Insuficiência placentária e hipóxia fetal.","B":"Desacelerações decorrentes de compressão funicular.","C":"Compressão do polo cefálico durante as contrações uterinas.","D":"Desacelerações variáveis devido à diminuição do líquido amniótico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784714","ankiGuid":"exx+YPUhAO"},{"id":"anki-obstetricia-vitalidade-fetal-59fc14d01801a57b","number":"0303h","sourceNumber":"0303h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Paciente 39 anos, G3P2A0, nenhum filho vivo, gestação de 32 semanas, hipertensa crônica de difícil controle, em uso de metildopa 2 gramas por dia e amlodipina 5mg por dia. Ultrassonografia mostra restrição de crescimento intraútero, circunferência abdominal percentil <10. Sobre a dopplervelocimetria fetal para esse caso, é CORRETO afirmar que:","options":{"A":"O último estágio do aumento da resistência na artéria umbilical identificado pelo doppler é a inversão do fluxo sanguíneo durante a diástole.","B":"A resistência ao fluxo sanguíneo nas artérias umbilicais é inversamente proporcional às condições da circulação uteroplacentária.","C":"Com a evolução da insuficiência uteroplacentária o aumento da resistência ao fluxo sanguíneo na artéria umbilical não impede o fluxo sanguíneo durante a diástole.","D":"O estado de centralização pode ser mensurado através do estudo da artéria cerebral média, que demonstrará diminuição do fluxo diastólico e da resistência em sua circulação."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784715","ankiGuid":"d6ZAl^FFBm"},{"id":"anki-obstetricia-vitalidade-fetal-2814aabda68d31e9","number":"0304h","sourceNumber":"0304h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 25 anos, 3G:2PN, chega ao pronto-socorro referindo dor em hipogástrio há 3 horas. Hoje com 33 semanas e 2 dias de gestação. Ao exame clínico: PA 113x76 mmHg, FC 74 bpm, presença de duas contrações uterinas por 10 minutos de fraca intensidade. Toque vaginal com colo grosso, posterior, pérvio para 3 cm, apresentação cefálica alta e móvel. Após analgesia, refere melhora das dores. Foi feita uma reavaliação do exame obstétrico que não demonstrou evolução do colo uterino, permanecendo com a mesma dilatação. Realiza a cardiotocografia apresentada.\n\nQual é a conclusão desta cardiotocografia?","options":{"A":"Reatividade fetal após estímulo.","B":"Ausência de movimentação fetal.","C":"Atividade uterina excessiva.","D":"Bem-estar fetal."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-c70bbfda5994951d60a2dd38048e4c9021eaebc3.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784716","ankiGuid":"deyV8zSI8W"},{"id":"anki-obstetricia-vitalidade-fetal-1c56605696e11f4d","number":"0305h","sourceNumber":"0305h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O aumento do pico sistólico da artéria cerebral média, na avaliação da anemia fetal, se deve por:","options":{"A":"Vasoconstrição periférica.","B":"Diminuição do retorno venoso.","C":"Diminuição da viscosidade sanguínea.","D":"Diminuição da contratilidade miocárdica."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784717","ankiGuid":"xwC.7y1m?v"},{"id":"anki-obstetricia-vitalidade-fetal-cd53b66ed4e720b0","number":"0306h","sourceNumber":"0306h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Paciente GIIIPIIAI, com 37 semanas e 5 dias de gravidez, é admitida na emergência com queixa de perda líquida há duas horas. Refere hipertensão arterial crônica em uso de 750mg/dia de metildopa. Ao exame de admissão, apresenta metrossístoles 1/10’/35”, BCF de 144bpm, movimentação fetal ativa. Ao toque vaginal, observa-se colo posterior, 50% apagado, 2cm dilatado, cefálico, líquido tinto de mecônio. A imagem a seguir refere-se à cardiotocografia realizada na admissão:\n\nNesse caso, a desaceleração encontrada no exame está relacionada à:","options":{"A":"hipertensão arterial crônica","B":"compressão do polo cefálico","C":"presença de líquido meconial","D":"rotura prematura de membranas ovulares"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-f0cf16e534b3eee23177993a0250064698ce0228.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784718","ankiGuid":"nH)^8z>D!#"},{"id":"anki-obstetricia-vitalidade-fetal-cb098e267bccb7a9","number":"0307h","sourceNumber":"0307h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"S.T.B., 36 anos, GII PI 1C A0, IG usg: 34 semanas, deu entrada no PSO com queixa de escotomas, dor em hipocôndrio direito e náuseas. PA de 150 x 100 mmHg. Nega aumento de PA prévio. Ausência de edema de membros inferiores. Rotina de pré-eclâmpsia: relação proteína na urina/creatinina na urina de 0,4, TGO 20, TGP 25, hb 11, htco: 33, plaquetas: 160.000, DHL 400, Bb totais de 0,8; Cr 0,9. Paciente submetida a ultrassom obstétrico com doppler que identificou: peso fetal no percentil 4, ILA normal, placenta anterior, GIII, feto em apresentação cefálica. Doppler de artéria umbilical, conforme imagem a seguir.\n\nDe acordo com a figura, assinale a interpretação correta do doppler fetal.","options":{"A":"Diástolo zero na artéria umbilical.","B":"Artéria umbilical com diástole reversa.","C":"Diminuição do índice de pulsatilidade em artéria umbilical.","D":"Aumento do índice de pulsatilidade em artéria cerebral média.","E":"Relação cérebro placentária normal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-5f60f90e57192f6bb4322155237b81a37c21f705.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784719","ankiGuid":"vf{bt(#7G["},{"id":"anki-obstetricia-vitalidade-fetal-721d82bdc4bf51e7","number":"0308h","sourceNumber":"0308h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Tercigesta, com ambas as gravidezes anteriores acometidas por pré-eclâmpsia, apresenta restrição de crescimento fetal intrauterino por insuficiência placentária. Encontra-se na 35ª semana de gestação, com dopplervelocimetria da artéria umbilical com diástole zero, mas com duto venoso normal. Qual é a conduta obstétrica indicada para essa paciente?","options":{"A":"Cesariana eletiva.","B":"Neuroproteção fetal.","C":"Perfil biofísico fetal a cada 3 dias.","D":"Dopplervelocimetria fetal a cada semana."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784720","ankiGuid":"sxH_j.^W!L"},{"id":"anki-obstetricia-vitalidade-fetal-e917a513b4f21649","number":"0309h","sourceNumber":"0309h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O objetivo primordial da avaliação fetal antenatal é identificar fetos de risco para eventos adversos ou para o óbito e, assim, atuar preventivamente para evitar o insucesso. O perfil biofísico fetal atinge sua máxima eficiência quando aplicado dentro do contexto clínico de cada caso. O perfil biofísico fetal avalia","options":{"A":"ILA, movimentação fetal, movimentos respiratórios fetais, cardiotocografia e tônus fetal.","B":"movimentos respiratórios fetais, artéria cerebral média, tônus fetal, ILA e movimentação fetal.","C":"ILA, movimentação fetal, cardiotocografia, maturidade placentária e movimentos respiratórios fetais.","D":"movimentos respiratórios fetais, ILA, ducto venoso, maturidade placentária e tônus fetal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784721","ankiGuid":"wSMW^Molqu"},{"id":"anki-obstetricia-vitalidade-fetal-30f92c5b7caaf4f5","number":"0310h","sourceNumber":"0310h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Analise a cardiotocografia na figura abaixo, segundo os parâmetros técnicos descritos: Velocidade da realização do exame: 1cm/minuto. Batimento cardíaco fetal (bpm) mínimo registrado na figura: 60 bpm. Batimento cardíaco fetal (bpm) máximo registrado na figura: 200 bpm. Variação do bpm registrada na figura: 20 bpm.\n\nAssinale a alternativa CORRETA.","options":{"A":"Trata-se de hipóxia fetal, sugerindo sofrimento fetal agudo.","B":"Observa-se uma síndrome de hiperestimulação uterina.","C":"Sugere-se compressão do cordão umbilical, com desaceleração de bom prognóstico.","D":"É provável uma compressão do polo cefálico, mediada pelo nervo vago.","E":"Sugere-se compressão do cordão umbilical, com desaceleração de prognóstico ruim."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-709ec50564703d4e0c4c49af583037f1a8a8005d.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784722","ankiGuid":"Jq!QeI?RiH"},{"id":"anki-obstetricia-vitalidade-fetal-8ba7853a04304b2e","number":"0311h","sourceNumber":"0311h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A dopplerfluxometria permite avaliar de forma mais apurada os territórios arterial e venoso e intervir mais oportunamente nas gestações de alto risco, em especial aquelas com crescimento intrauterino restrito. Em condições fisiológicas, com feto saudável, as resistências nas artérias umbilical e cerebral média, respectivamente, estão:","options":{"A":"diminuída / diminuída","B":"diminuída / aumentada","C":"aumentada / diminuída","D":"aumentada / aumentada"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784723","ankiGuid":"Q<*S&.3x*="},{"id":"anki-obstetricia-vitalidade-fetal-51bbe1e0aff5f22c","number":"0312h","sourceNumber":"0312h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Durante a condução de um parto por via vaginal, aos 6 centímetros de dilatação, foi realizado exame cardiotocográfico que mostrou a ocorrência de desacelerações periódicas da frequência cardíaca fetal, após as contrações uterinas (DIP II ou tardio). Este quadro é observado nos casos de:","options":{"A":"Hipóxia fetal por insuficiência placentária.","B":"Hipóxia fetal secundária à compressão do cordão umbilical.","C":"Hipóxia fetal devido a hiperventilação materna durante as contrações uterinas.","D":"Hipóxia fetal decorrente de estímulo vagal devido à compressão do polo cefálico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784724","ankiGuid":"zJIYK[^&.s"},{"id":"anki-obstetricia-vitalidade-fetal-f0d5640575db78fe","number":"0313h","sourceNumber":"0313h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Assinale a assertiva correta sobre a avaliação do bem-estar fetal.","options":{"A":"Paciente com 23 semanas de gestação, normotensa, com eco-Doppler de artérias uterinas alterado, deve ser internada para rastrear pré-eclâmpsia e realizar avaliação com perfil biofísico fetal.","B":"Paciente com 28 semanas de gestação, com diabetes gestacional, com peso fetal no percentil 80, deve realizar eco-Doppler das artérias umbilicais frequentemente, para prevenir acidose metabólica e óbito fetal inesperado.","C":"Paciente com 29 semanas de gestação, cujo feto apresenta restrição de crescimento e vasodilatação da artéria cerebral média ao eco-Doppler, deve ser internada para receber imediatamente corticosteroide e ter a gestação interrompida após 48 horas.","D":"Paciente com 34 semanas de gestação, em avaliação após acidente de carro, com sinais de contusão abdominal, inicialmente sem sangramento e sem contrações, com feto vivo, deve ser monitorizada por 24 horas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784725","ankiGuid":"jdTIauC(_."},{"id":"anki-obstetricia-vitalidade-fetal-6a0bbbe04f62aa16","number":"0314h","sourceNumber":"0314h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Mulher, 34a, G4P1C1A2, idade gestacional de 38 semanas e 6 dias, procura atendimento por início de contrações ontem e piora da dor hoje. Nega perdas vaginais e sangramento. Refere boa movimentação fetal. Sem comorbidades. Exame obstétrico: dinâmica uterina=2 contrações fracas de 30 segundos em 10 minutos, altura uterina= 38 cm, BCF= 146 bpm, cefálico. Toque vaginal= colo dilatado 1 polpa, grosso, posterior. Cardiotocografia:\n\nA CONDUTA É:","options":{"A":"Internar para indução de parto.","B":"Internar para cesárea.","C":"Dar alta com orientações sobre o trabalho de parto.","D":"Dar alta e indicar cardiotocografia a cada 3 dias."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-17c2bfa5db60ff63228a336d443b920256ea797e.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784726","ankiGuid":"wxjsR#RJph"},{"id":"anki-obstetricia-vitalidade-fetal-25e46bf3f33d5286","number":"0315h","sourceNumber":"0315h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A cardiotocografia (CTG) anteparto é um exame de vitalidade fetal. Consiste no registro, por cerca de 20 minutos, da frequência cardíaca fetal, das contrações uterinas e da movimentação fetal. Sobre esse exame, informe se é verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com a sequência correta. ( ) São avaliados 4 parâmetros na cardiotocografia: frequência cardíaca fetal, oscilações da frequência cardíaca fetal, acelerações da frequência cardíaca fetal à movimentação materna e desacelerações da frequência cardíaca fetal. ( ) A FCF (Frequência Cardíaca Fetal) média é de 110 a 160 bpm. Classifica-se como taquicardia quando a frequência é maior que 160 bpm. ( ) A CTG é classificada em 3 categorias: categoria I como normal, categoria II como anormal e categoria III como indeterminada/atípica. ( ) Evitar período prévio de jejum prolongado para realização de CTG.","options":{"A":"V – V – V – F.","B":"F – V – V – V.","C":"V – V – F – V.","D":"F – V – F – V.","E":"V – V – V – V."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784727","ankiGuid":"i?__5zBG^-"},{"id":"anki-obstetricia-vitalidade-fetal-f2f794f73aad3225","number":"0316h","sourceNumber":"0316h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A dopplerfluxometria obstétrica avalia a vitalidade fetal no 3º trimestre, através do estudo dos seguintes vasos:","options":{"A":"artérias umbilicais, artérias cerebrais média e veia umbilical.","B":"artérias uterinas, artérias umbilicais e artérias cerebrais média.","C":"veia umbilical, ducto venoso e artérias uterinas.","D":"ducto venoso, artérias uterinas e artérias cerebrais média."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784728","ankiGuid":"J1`|r~pxi$"},{"id":"anki-obstetricia-vitalidade-fetal-f70244952eb11c65","number":"0317h","sourceNumber":"0317h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Na cardiotocografia, os parâmetros avaliados com relação aos batimentos cardíacos fetais são:","options":{"A":"frequência basal, arritmias, intermitência, acelerações e desacelerações.","B":"frequência basal, oscilações da frequência, arritmias, acelerações e desacelerações.","C":"arritmias, intermitência, variabilidade, acelerações e desacelerações.","D":"frequência basal, oscilações da frequência, variabilidade, acelerações e desacelerações."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784729","ankiGuid":"DF^D6:}k=D"},{"id":"anki-obstetricia-vitalidade-fetal-d6892529f89dd257","number":"0318h","sourceNumber":"0318h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Na presença de hipoxia fetal ocorre redistribuição central do fluxo sanguíneo, aumentando para os órgãos que precisam ser priorizados, como","options":{"A":"os rins, o fígado e os pulmões.","B":"o cérebro, o coração e os rins.","C":"o cérebro, o coração e o fígado.","D":"o cérebro, o coração e as adrenais."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784730","ankiGuid":"c3pFgq$L%U"},{"id":"anki-obstetricia-vitalidade-fetal-72a9ad76314ae42e","number":"0319h","sourceNumber":"0319h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta de termo encontra-se no período expulsivo há uma hora, a variedade de posição é OEA, no plano +3 de DeLee, quando é detectado líquido meconial +++/4. Cardiotocografia: desacelerações tardias em mais de 50% das contrações. Qual é a melhor conduta?","options":{"A":"Aumentar o fluxo de ocitocina e estimular puxos prolongados.","B":"Aguardar o delivramento espontâneo, mantendo a vigilância do bem-estar fetal.","C":"Cesárea imediata.","D":"Uso imediato do vacuoextrator ou fórcipe."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784731","ankiGuid":"g.5c2ZAK~R"},{"id":"anki-obstetricia-vitalidade-fetal-94a968ffd7d97c75","number":"0320h","sourceNumber":"0320h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta de 41 semanas, 28 anos de idade, relata diminuição da movimentação fetal. Pré-natal sem complicações, feto com crescimento e desenvolvimento normais. Exame físico: bom estado geral, sinais vitais normais, altura uterina 34 cm, BCF 140 bpm, dinâmica uterina ausente. Toque: apresentação cefálica, plano –2, colo pérvio para 2 cm, 40% de esvaecimento e bolsa íntegra. Perfil biofísico fetal de 8 com a seguinte cardiotocografia:\n\nQual é a interpretação da cardiotocografia e a conduta?","options":{"A":"Tranquilizador; retorno para reavaliação em 3 dias.","B":"Não tranquilizador; realizar cesárea.","C":"Reativo; iniciar indução com ocitocina.","D":"Não reativo; prolongar o traçado; iniciar preparo de colo com misoprostol."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-f8a5780a549e001dc27946614a98fb7543bb2306.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784732","ankiGuid":"rl,.UpbH@4"},{"id":"anki-obstetricia-vitalidade-fetal-70629a2777197bc9","number":"0321h","sourceNumber":"0321h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta de 25 anos de idade, 39 semanas de gestação, está em trabalho de parto há 10 horas. A analgesia peridural foi instalada há 6 horas. No momento 8 cm de dilatação do colo uterino, inalterado há 2 horas. Dinâmica uterina com 5 contrações fortes em 10 minutos. Cardiotocografia com BCF de 140 bpm, variabilidade diminuída, sem acelerações transitórias, nem desacelerações. Na inspeção, observa-se a figura a seguir.\n\nQual é a conduta obstétrica?","options":{"A":"Sondagem vesical.","B":"Ocitocina endovenosa.","C":"Complementar analgesia.","D":"Cesárea imediata."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-c5cfa036fd208c36e9daee461d7ab5e62c1a3c1b.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784733","ankiGuid":"P3U3]vDFC%"},{"id":"anki-obstetricia-vitalidade-fetal-72d571702cdb41e8","number":"0322h","sourceNumber":"0322h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 17 anos de idade, com 40 semanas e 3 dias de gestação comparece assintomática para controle de vitalidade. Ao exame clínico: PA 110x75 mmHg, FC 78 bpm, altura uterina 36 cm, toque com colo amolecido, grosso, posterior, pérvio para 2 cm, apresentação cefálica no plano -2 de DeLee. Na avaliação ultrassonográfica, feto com tônus preservado, índice de líquido amniótico de 4.6 cm, movimentos fetais e respiratórios presentes. Cardiotocografia apresentada.\n\nQual é a conduta obstétrica?","options":{"A":"Indução do parto com ocitocina.","B":"Reavaliação de vitalidade fetal em 48 horas.","C":"Parto cesáreo segmentar transversa.","D":"Maturação do colo uterino com prostaglandina."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-a28dfe483cd1ca7dbdf4208a60635378a7ac098c.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784734","ankiGuid":"CcEE1,F>Q$"},{"id":"anki-obstetricia-vitalidade-fetal-5408da21afde86b4","number":"0323h","sourceNumber":"0323h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Com relação ao perfil biofísico fetal como método de avaliação da vitalidade fetal, assinale a correta.","options":{"A":"I. Para sua execução são necessários o uso da cardiotocografia e do ultrassom.","B":"II. Os marcadores agudos deste exame são a frequência cardíaca fetal, movimentos respiratórios fetais, movimentos corporais fetais e tônus fetal.","C":"III. O marcador crônico deste exame é o líquido amniótico.","D":"As afirmativas I e II são verdadeiras. A afirmativa III é falsa.","E":"As afirmativas I e III são verdadeiras. A afirmativa II é falsa.","F":"As afirmativas II e III são verdadeiras. A afirmativa I é falsa.","G":"As afirmativas I, II e III são verdadeiras.","H":"As afirmativas I, II e III são falsas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784735","ankiGuid":"nL|eJ}}Y;i"},{"id":"anki-obstetricia-vitalidade-fetal-a50ba5b9249c1b6b","number":"0324h","sourceNumber":"0324h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Segundo o Colégio Americano de Obstetras e Ginecologistas, a monitorização fetal abaixo é classificada como categoria:","options":{"A":"1.","B":"2.","C":"3.","D":"4."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-60fe1e6d82c6627b37aa034ea661519d1b68a91d.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784736","ankiGuid":"P2(zQCo:X$"},{"id":"anki-obstetricia-vitalidade-fetal-2709c630a962173c","number":"0325h","sourceNumber":"0325h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Parturiente, G3 P2 (partos vaginais), 39 semanas de gestação, apresenta dinâmica uterina de duas a três contrações fortes, de 40 segundos de duração, em 10 minutos. Ao exame de toque: colo fino, centralizado, dilatado em 8 cm, bolsa íntegra, OEA e plano +3 de De Lee. Realizada cardiotocografia, foi constatado o traçado da imagem a seguir.\n\nA melhor conduta a ser adotada nesse momento é:","options":{"A":"Indicar a interrupção imediata pela operação cesariana.","B":"Estimular os puxos maternos para abreviação do trabalho de parto.","C":"Amniotomia e amnioinfusão para redução na compressão de cordão.","D":"Posicionar em decúbito lateral esquerdo e expansão intravenosa de volume."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-5591f9f18f7572e63cb10a3967ad09ccf814b986.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784737","ankiGuid":"kNmYCC`4zc"},{"id":"anki-obstetricia-vitalidade-fetal-64760951511d3571","number":"0326h","sourceNumber":"0326h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta, 28 anos de idade, 30 semanas de gestação, refere diminuição da movimentação fetal. Foi submetida a exame de cardiotocografia conforme apresentado na imagem.\n\nNesse caso, a denominação do padrão da cardiotocografia anteparto e o próximo passo na conduta a ser adotada para o melhor cuidado da gestante, respectivamente, são:","options":{"A":"Hiporeativo; interromper a gestação por cesárea.","B":"Não reativo; realizar perfil biofísico fetal.","C":"Não tranquilizador; realizar teste de tolerância às contrações uterinas.","D":"Inativo; realizar cardiotocografia computadorizada."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-3053068bb87129bfaf9494aed445a89d61cba5cc.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784738","ankiGuid":"pg_Nl:^$s)"},{"id":"anki-obstetricia-vitalidade-fetal-98d36f6ac7bb6e4b","number":"0327h","sourceNumber":"0327h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O estudo Dopplerfluxométrico do sonograma do ducto venoso:","options":{"A":"identifica a vasoconstrição periférica, que leva à diminuição da pressão nas câmaras cardíacas, seguida de alterações no território venoso fetal.","B":"tem sido eleito pela maioria dos estudos para representar o território venoso fetal.","C":"visualiza o shunt vascular que comunica a porção intra-hepática da veia umbilical com a veia cava inferior e daí para o átrio esquerdo, levando sangue oxigenado para o forame magno.","D":"é caracterizado por baixa velocidade durante a sístole ventricular (onda-S) e a diástole (onda-D), determinando um padrão sonográfico bifásico característico.","E":"é caracterizado por grande aumento da velocidade na contração atrial (onda-A), determinando um padrão sonográfico monofásico característico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784739","ankiGuid":"p?Q>%XJ[jq"},{"id":"anki-obstetricia-vitalidade-fetal-fe6b78d276380985","number":"0328h","sourceNumber":"0328h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Tercigesta, 32 anos, dois partos normais anteriores, fazia pré-natal em Unidade de Alto Risco devido hipertensão arterial. Está internada em trabalho de parto, 5 cm de dilatação. 3 contrações em 10 minutos de observação e apresentação cefálica. O exame cardiotocográfico abaixo foi realizado agora.\n\nDe acordo com esses dados, a conduta é:","options":{"A":"Cesariana de emergência:","B":"Parto via vaginal instrumentalizado.","C":"Amniotomia e oxigenação materna.","D":"Reposicionamento materno - decúbito lateral esquerdo materno."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-a8bf167bf3398f7b5e7f3d1fac650b3738013728.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784740","ankiGuid":"i&/K8}>4-y"},{"id":"anki-obstetricia-vitalidade-fetal-bd93df81b57331a9","number":"0329h","sourceNumber":"0329h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 32 semanas com hipertensão arterial crônica e restrição de crescimento fetal. Apresenta dopplervelocimetria obstétrica da artéria umbilical conforme a imagem em anexo.\n\nQual é a conduta?","options":{"A":"Resolução imediata da gestação.","B":"Avaliação diária do ducto venoso.","C":"Avaliação diária da artéria uterina.","D":"Seguimento no pré-natal de rotina.","E":"Repetir dopplervelocimetria em uma semana."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-97854e7eb3f7792804dabcacf89b56b820ebbcfe.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784741","ankiGuid":"P/F@h(a0r6"},{"id":"anki-obstetricia-vitalidade-fetal-8f2ac14525b4ed65","number":"0330h","sourceNumber":"0330h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 38 semanas, com hipertensão arterial crônica em uso de aspirina, cálcio e metildopa, chega à maternidade devido a contrações uterinas e diminuição da movimentação fetal. Nega outras queixas. Ao exame constata-se PA 150/100 mmHg, edema 3+/4 de membros inferiores, AU 32 cm, BCF 145 bpm, TV colo grosso e impérvio, dinâmica uterina de duas contrações em 10 min. Foi realizada cardiotocografia, com imagem em anexo.\n\nQual é a classificação da cardiotocografia e qual é a conduta?","options":{"A":"Categoria 2, resolução imediata da gestação.","B":"Categoria 3, resolução da gestação se as medidas de ressuscitação intrauterina não forem efetivas.","C":"Categoria 1, solicitar dopplervelocimetria obstétrica; se normal, liberar a gestante.","D":"Categoria 2, medidas de ressuscitação intrauterina e resolução da gestação se as medidas não forem efetivas para melhorar os parâmetros fetais.","E":"Categoria 3, solicitar dopplervelocimetria obstétrica para avaliar o ducto venoso."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-4d3fdf425c093a967f5ab7524391bc9298f7b1c7.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784742","ankiGuid":"g8EV<Fkk7;"},{"id":"anki-obstetricia-vitalidade-fetal-9f4149bede47267d","number":"0331h","sourceNumber":"0331h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Mulher de 28 anos, com 38 semanas de idade gestacional interna em trabalho de parto. Cardiotocografia (CTG) mostrando padrão sinusoide. Ao exame: PA 120x80 mmHg, frequência cardíaca materna 88 bpm, tônus uterino normal, 3 contrações em 10 minutos com 40 segundos de duração (3/10'/40\"\"), feto único, longitudinal, cefálico com dorso a esquerda, batimentos cardíacos fetais (BCF) 110bpm. Colo 6 cm dilatado, 70% apagado, bolsa íntegra. Após manobras de ressuscitação intrauterina, CTG manteve padrão sinusoide. Qual melhor conduta?","options":{"A":"Iniciar ocitocina.","B":"Realizar amniotomia.","C":"Realizar amnioscopia.","D":"Cesariana.","E":"Analgesia de parto."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784743","ankiGuid":"Lp/{u56F~."},{"id":"anki-obstetricia-vitalidade-fetal-dff62d62927c9adb","number":"0332h","sourceNumber":"0332h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Em exame de cardiotocografia demonstrando traçado de ondas em formato de sino, monótonas, com ritmo fixo e regular, tem o nome de","options":{"A":"Acelerações transitórias.","B":"Desacelerações.","C":"Padrão sinusoidal.","D":"DIP II."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784744","ankiGuid":"lNUOZA<KuM"},{"id":"anki-obstetricia-vitalidade-fetal-9ebde68d1831bdf4","number":"0333h","sourceNumber":"0333h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Na avaliação de vitalidade fetal intraparto, assinale a INCORRETA:","options":{"A":"As desacelerações precoces, em geral, são consideradas benignas e sem consequências para o feto, pois não estão associadas com acidemia.","B":"Nas desacelerações tardias, o nadir ocorre após o pico da contração uterina, em resposta à diminuição do fluxo sanguíneo uterino para o feto.","C":"No traçado anormal de cardiotografia categoria III, reflete aumento do risco de acidose fetal.","D":"Acelerações transitórias da frequência cardíaca é sinal de acidemia fetal, devendo o parto ser realizado o mais breve possível."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784745","ankiGuid":"oK<j+n<hC;"},{"id":"anki-obstetricia-vitalidade-fetal-28f91dd5c3e87128","number":"0334h","sourceNumber":"0334h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A insuficiência placentária pode levar a um quadro de alterações circulatórias que se caracterizam pela tendência a:","options":{"A":"elevação da resistência nas artérias umbilicais e cerebral média","B":"diminuição da resistência nas artérias umbilicais e cerebral média","C":"elevação da resistência nas artérias umbilicais e diminuição da resistência na artéria cerebral média","D":"diminuição da resistência nas artérias umbilicais e aumento da resistência na artéria cerebral média"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784746","ankiGuid":"cAXpXu4PP,"},{"id":"anki-obstetricia-vitalidade-fetal-2bfcd7d0c97b20c7","number":"0335h","sourceNumber":"0335h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Multigesta (G4P2A 1), 37 anos, interna na fase ativa do trabalho de parto espontâneo, com 37,5 semanas. Exame físico geral normal, altura uterina 37 cm. A evolução do trabalho de parto, até às 20h, está demonstrada no partograma (Figura 1).\n\nNesse momento, a equipe decidiu por monitorizar o feto continuamente devido à ausculta de desacelerações de sua frequência cardíaca (Figura 2).\n\nQual alternativa tem diagnósticos nesse cenário clínico?","options":{"A":"Período expulsivo prolongado com asfixia fetal.","B":"Trabalho de parto eutócico com suspeita de sofrimento fetal.","C":"Distocia funcional com vitalidade fetal esperada para expulsivo.","D":"Evolução normal do trabalho de parto com boa vitalidade fetal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-18a4a27d583d836e002b2091cd134ba5edb28fc2.png","question_bank/media/obstetricia-vitalidade-fetal/paste-5ea958515d24f2aa978b72b5b08bfb504059a725.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784747","ankiGuid":"eSLqea[d+#"},{"id":"anki-obstetricia-vitalidade-fetal-28961606dcbf5c92","number":"0336h","sourceNumber":"0336h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta, 18 anos, com 34 semanas de gestação, retorna em consulta pré-natal, em Unidade Básica de Saúde, com resultado de ultrassonografia obstétrica realizada há 3 dias. É tabagista e tem índice de massa corporal no primeiro trimestre de 17 kg/m² • Está assintomática, com exames da rotina laboratorial normais. A ultrassonografia mostrou peso fetal estimado no percentíl 12, índice de pulsatilidade (IP) na artéria umbilical no percentíl 91 e IP na artéria cerebral média no percentil 15, maior bolsão de líquido amniótico no percentil 25. Na consulta de hoje não foram percebidos movimentos fetais. O exame físico geral e restante do exame obstétrico são normais. Qual é a conduta imediata mais adequada neste momento?","options":{"A":"Auscultar o feto após estímulo mecânico ou vibroacústico.","B":"Solicitar nova ultrassonografia obstétrica com Doppler em uma semana.","C":"Encaminhar a paciente ao serviço de referência de urgência.","D":"Agendar avaliação dessa gestante em pré-natal de alto risco."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784748","ankiGuid":"g@2XL6UPur"},{"id":"anki-obstetricia-vitalidade-fetal-1141f2e5548b46d2","number":"0337h","sourceNumber":"0337h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A ocorrência de DIP I (precoce) observada na cardiotocografia intraparto indica","options":{"A":"esposta fisiológica à hiperventilação materna durante a contração uterina.","B":"resposta fisiológica fetal à redução do fluxo nas artérias umbilicais durante a contração uterina.","C":"reflexo vagal por compressão do polo cefálico durante a contração uterina.","D":"relação com a asfixia fetal por insuficiência uteroplacentária aguda.","E":"centralização fetal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784749","ankiGuid":"nE;1v6B8U5"},{"id":"anki-obstetricia-vitalidade-fetal-586c474eeb799bef","number":"0338h","sourceNumber":"0338h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A centralização fetal, que ocorre em determinados casos de gestação de alto risco, pode ser identificada através do exame denominado","options":{"A":"cardiotocografia.","B":"ecocardiografia fetal.","C":"ecografia morfológica fetal.","D":"dopplervelocimetria fetal.","E":"ultrassonografia transvaginal."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784750","ankiGuid":"wVyY+L2$2$"},{"id":"anki-obstetricia-vitalidade-fetal-8ad770a2c282043e","number":"0339h","sourceNumber":"0339h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Paciente de 15 anos, G2P0A1, atualmente com 37 semanas de gestação, em seguimento em pré-natal de alto risco devido à síndrome hipertensiva gestacional. Realizou ultrassonografia obstétrica com doppler, evidenciando oligoâmnio e restrição de crescimento intrauterino. Indicada resolução da gestação, sendo encaminhada à maternidade para indução do parto, após cardiotocografia para avaliar a vitalidade fetal, conforme imagem a seguir.\n\nO traçado ao lado é classificado como","options":{"A":"inconclusivo.","B":"categoria I.","C":"categoria II.","D":"categoria III.","E":"categoria IV."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-ffca0ba15f2da09f967f1344da0dc320d4230992.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784751","ankiGuid":"YCV1o>#}`"},{"id":"anki-obstetricia-vitalidade-fetal-d6c5a9906d2c5b93","number":"0340h","sourceNumber":"0340h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O perfil biofísico fetal é um exame solicitado para avaliar a vitalidade fetal muito utilizado para pacientes portadoras de diabetes gestacional ou com gestação múltipla. Sobre o perfil biofísico fetal, considere as afirmativas seguintes. I. É um exame capaz de detectar sofrimento fetal agudo. II. Deve ser feito observando os parâmetros por, pelo menos, 30 minutos. III. O primeiro parâmetro a se alterar são os movimentos corporais. IV. O líquido amniótico é um marcador agudo de sofrimento fetal. V. Diante de resultados abaixo ou iguais a 4, deve-se realizar o parto imediatamente. Estão corretas","options":{"A":"I, II e V, somente.","B":"I, II, III e V, somente.","C":"I, III, IV e V, somente.","D":"II e IV, somente.","E":"II, III e IV, somente."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784752","ankiGuid":"L~$?v-B;&R"},{"id":"anki-obstetricia-vitalidade-fetal-54c335d726a0efdd","number":"0341h","sourceNumber":"0341h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Sobre Vitalidade fetal, marque a alternativa CORRETA:","options":{"A":"O sonograma da arterial umbilical representa a circulação coronariana fetal.","B":"A presença da incisura protodiastólica após de 26 semanas de gestação prediz bem-estar fetal.","C":"O perfil biofísico fetal, com o objetivo de avaliar o bem-estar fetal, é realizado pela ultrassonografia durante um período de 30 minutos utilizando quatro parâmetros mais a cardiotocografia, são eles: líquido amniótico, tônus, movimentos fetal ativos e circulação fetal.","D":"A artéria cerebral média é o vaso mais estudado no feto e quando alterado, relaciona-se com resultados perinatais adversos.","E":"A Cardiotocografia normal (reativo) inclui uma aceleração a cada 20 minutos de traçado, com amplitude maior ou igual a 10 bpm e duração acima de 15 segundos."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784753","ankiGuid":"zTmMt|;[+d"},{"id":"anki-obstetricia-vitalidade-fetal-5d90357f4743cb54","number":"0342h","sourceNumber":"0342h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Em relação à hemodinâmica fetal, assinale a opção correta.","options":{"A":"O ducto arterioso é o primeiro shunt da circulação fetal.","B":"A irrigação de membros superiores, crânio e coração é feita pelo lado direito do coração fetal.","C":"O último parâmetro de avaliação Doppler a se alterar em um quadro de hipoxia fetal é a artéria cerebral média.","D":"As artérias umbilicais são ramos terminais das ilíacas internas.","E":"O forame oval é uma veia de pequeno calibre que desvia o sangue para o ventrículo direito."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784754","ankiGuid":"gwF08TGZJ"},{"id":"anki-obstetricia-vitalidade-fetal-3918388c1ab55d57","number":"0343h","sourceNumber":"0343h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Parturiente de 39 semanas e 4 dias, primigesta, chega ao pronto-socorro com queixa de dor em baixo ventre. Nega patologias obstétricas ou clínicas. Ao exame físico, apresenta-se corada e hidratada, PA: 120 x 80mmHg, FC 80bpm. Altura uterina: 34cm, dinâmica uterina: 3 contrações fortes em 10 minutos; ao toque vaginal, colo com dilatação de 4cm, médio, -1 De Lee. Observe a cadiotocografia apresentada a seguir.\n\nBaseando-se na cadiotocografia, qual é a classificação do traçado e a conduta correta?","options":{"A":"Categoria III, esforços imediatos para reverter o padrão ou resolução parto.","B":"Categoria 0, sem conduta específica, controle habitual do trabalho de parto.","C":"Categoria II, oxigenioterapia e cardiotocografia contínua.","D":"Categoria I, aguardar resolução parto.","E":"Categoria II, aguardar a resolução do parto."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-cfc44920f7a095074ba96cf3130ff8af985f5fe6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784755","ankiGuid":"w.W[p+aNV7"},{"id":"anki-obstetricia-vitalidade-fetal-be3e2a0140e329d9","number":"0344h","sourceNumber":"0344h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"G1P0, 40 semanas, comparece em consulta de rotina do pré-natal, sem queixas. Ao exame físico, dinâmica uterina ausente, colo grosso, posterior, fechado. Cardiotocografia mostrando feto hipoativo e hiporreativo. Ultrassonografia mostra: apresentação cefálica, índice de líquido amniótico de 4,0 cm, maior bolsão vertical de 3,0 cm, perfil biofísico fetal: 8 em 8. Qual é a melhor conduta?","options":{"A":"Repetir cardiotocografia em uma semana.","B":"Indução do trabalho de parto com ocitocina.","C":"Internação para cesárea.","D":"Indução do trabalho de parto com prostaglandina vaginal.","E":"Aguardar trabalho de parto espontâneo até 42 semanas."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784756","ankiGuid":"f}h~#!IyM1"},{"id":"anki-obstetricia-vitalidade-fetal-9d8c61931e4686c6","number":"0345h","sourceNumber":"0345h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O fenômeno de centralização fetal diagnosticado pelo Doppler obstétrico representa:","options":{"A":"Artéria Umbilical com fluxo de baixa resistência e ducto venoso com onda A positiva.","B":"Artéria cerebral média com fluxo de alta resistência e Ducto venoso com onda A negativa.","C":"Artéria cerebral média com fluxo de baixa resistência, artéria umbilical com fluxo de alta resistência.","D":"Artéria cerebral média com fluxo de baixa resistência, artéria umbilical com fluxo de baixa resistência."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784757","ankiGuid":"w6/0aw&Lm."},{"id":"anki-obstetricia-vitalidade-fetal-c0aa6adcf090a9ae","number":"0346h","sourceNumber":"0346h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Os métodos de avaliação da vitalidade fetal buscam avaliar o bem-estar do feto e, por conseguinte, evitar uma morte perinatal. Dentre tais métodos, se encontra o teste de contração com estresse, o qual pode revelar se o bebê tem uma frequência cardíaca anormal durante as contrações. Quanto ao teste de contração com estresse, é CORRETO afirmar:","options":{"A":"É utilizado um cardiotocógrafo para registrar a frequência cardíaca fetal e a atividade uterina.","B":"É “negativo” quando não ocorrem acelerações tardias.","C":"É o mais trabalhoso dentre os métodos, além de possuir menor precisão para detectar um feto comprometido.","D":"As contrações são induzidas por meio de estimulação mamilar da gestante."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784758","ankiGuid":"A|t&iSVjAs"},{"id":"anki-obstetricia-vitalidade-fetal-5bc069377f2a26ab","number":"0347h","sourceNumber":"0347h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O estudo dopplerfluxométrico do sonograma do ducto venoso","options":{"A":"identifica a vasoconstrição periférica, que leva à diminuição da pressão nas câmaras cardíacas, seguida de alterações no território venoso fetal.","B":"tem sido eleito pela maioria dos estudos para representar o território venoso fetal.","C":"visualiza o shunt vascular que comunica a porção intra-hepática da veia umbilical com a veia cava inferior e daí para o átrio esquerdo, levando sangue oxigenado para o forame magno.","D":"é caracterizado por baixa velocidade durante a sístole ventricular (onda-S) e a diástole (onda-D), determinando um padrão sonográfico bifásico característico.","E":"é caracterizado por grande aumento da velocidade na contração atrial (onda-A), determinando um padrão sonográfico monofásico característico."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784759","ankiGuid":"Gcn[m&JZW5"},{"id":"anki-obstetricia-vitalidade-fetal-714ce471ab7681fa","number":"0348h","sourceNumber":"0348h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 43 anos de idade, casada, está em consulta pré-natal após submeter-se a reprodução assistida. É primigesta e tem 33 semanas de gestação. Na avaliação clínica, está em bom estado geral, corada, PA 120 x 75mmHg, FC 78 bpm, IMC 21,4 kg/m². A altura uterina é de 31 cm. O BCF está presente e é rítmico. Tônus normal.\n\nTraz ultrassonografia obstétrica mostrando feto único, cefálico, com dorso à esquerda e placenta posterior. Índice de líquido amniótico 9 cm e peso estimado 1685g (percentil 5).\n\nNa mesma consulta foi realizada a seguinte avaliação de vitalidade fetal:\n\nValores de referência:\nA umb PI: 030 a 1,40\nA umb S/D: 1,24 a 3,40\n\nA orientação a ser dada à paciente quanto à resolução da gravidez é:","options":{"A":"Indicar parto com 34 semanas de gestação.","B":"Programar parto no termo precoce.","C":"Aguardar termo tardio.","D":"Aguardar até 40 semanas de gestação."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-20b734ca4859e31157a8564472c49e153f3304f1.png","question_bank/media/obstetricia-vitalidade-fetal/paste-749fa69b2e63e48d7d78a0766fddeecce9d62495.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784760","ankiGuid":"P-v~Rw6zID"},{"id":"anki-obstetricia-vitalidade-fetal-0b2d7d79ed2f9537","number":"0349h","sourceNumber":"0349h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta de 21 anos de idade, está com 38 semanas de gestação e iniciou trabalho de parto espontâneo. O partograma e a cardiotocografia estão apresentados a seguir.\n\nQual é o método indicado para ultimação do parto?","options":{"A":"Abreviação com vácuo extrator.","B":"Cesárea segmentar transversa.","C":"Aguardar parto espontâneo.","D":"Rotação com fórcipe Kielland."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-b822eeeb98f8275fb0b8b60b6e4f83e784c2fa03.png","question_bank/media/obstetricia-vitalidade-fetal/paste-45096a4c5f0eb922d9f5d19e52b76087fe58a7f6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784761","ankiGuid":"be/McC~1Q9"},{"id":"anki-obstetricia-vitalidade-fetal-879cbe02e1c9cbe2","number":"0350h","sourceNumber":"0350h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta de 21 anos de idade, está com 38 semanas de gestação e iniciou trabalho de parto espontâneo. O partograma e a cardiotocografia estão apresentados a seguir.\n\nA fisiopatologia do traçado da cardiotocografia apresentado inclui:","options":{"A":"Compressão funicular.","B":"Compressão do pólo cefálico.","C":"Bloqueio átrio ventricular fetal.","D":"Acidemia fetal"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-b822eeeb98f8275fb0b8b60b6e4f83e784c2fa03.png","question_bank/media/obstetricia-vitalidade-fetal/paste-45096a4c5f0eb922d9f5d19e52b76087fe58a7f6.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784762","ankiGuid":"K|zT`BZ;Hd"},{"id":"anki-obstetricia-vitalidade-fetal-1f04572e127761d4","number":"0351h","sourceNumber":"0351h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"É um dos critérios de cardiotocografia com resultado de feto ativo e reativo:","options":{"A":"frequência cardíaca fetal máxima de 160 batimentos por minuto após estímulo sonoro.","B":"variabilidade entre 5 a 10 batimentos por minuto antes do estímulo.","C":"linha de base entre 100 e 200 batimentos por minuto antes do estímulo.","D":"presença de acelerações transitórias após movimentação ou estímulo sonoro.","E":"presença de no máximo uma desaceleração não relacionada ao estímulo sonoro."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784763","ankiGuid":"gD@PX{_9o("},{"id":"anki-obstetricia-vitalidade-fetal-cc53872109e4ea5b","number":"0352h","sourceNumber":"0352h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"No acompanhamento do crescimento intrauterino restrito placentário precoce, realizou-se um Doppler de artéria umbilical com 23 semanas. Pode-se afirmar, correlacionando o resultado encontrado no exame e a conduta futura, que:","options":{"A":"com diástole zero, repetir em 2 semanas e parto entre 30-32 semanas.","B":"com Doppler normal, repetir a cada 15 dias e parto com 38 semanas.","C":"com diástole reduzida, repetir o Doppler em 2 semanas e parto com 37 semanas.","D":"com diástole reversa, realizar Doppler de ducto venoso e parto em 24 horas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784764","ankiGuid":"x:7}%=]~Z"},{"id":"anki-obstetricia-vitalidade-fetal-b96009fc200cb4aa","number":"0353h","sourceNumber":"0353h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante, 39 semanas e 2 dias está em monitorização contínua com cardiotocografias intraparto. Durante o trabalho de parto, ocorreram desacelerações que tiveram seu início, máximo de queda e recuperação à linha de base coincidindo, respectivamente, com o começo, pico e fim da contração, sendo que a frequência cardíaca fetal basal associada situava-se nos limites da normalidade. Esse tipo de desacelerações pode ser classificado como:","options":{"A":"tardio.","B":"cefálico.","C":"umbilical.","D":"placentário."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784765","ankiGuid":"E<9nTGt@XK"},{"id":"anki-obstetricia-vitalidade-fetal-db4e74d1fda5a471","number":"0354h","sourceNumber":"0354h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta de 22 anos inicia pré-natal (PN) com 14 semanas. Está assintomática, altura do fundo uterino (AFU) = 13cm, batimentos cardíacos fetais (BCF) = 160bpm, colo longo, posterior e fechado, PA = 110 x 70mmHg, rotina PN sem alterações. Até a 29ª semana, a gestação evolui sem intercorrências clínicas ou laboratoriais. Na consulta com 33 semanas, apresenta AFU = 25cm, BCF = 155bpm, PA = 165 x 115mmHg, com queixa de cefaleia esporádica. Os exames realizados na 32ª semana revelaram: Ht = 36; Hg = 11,5; U = 42; C = 1,0; Ptn 24h = 4.500mg. A médica solicita USG, cujo laudo indica oligodramnia e feto com peso abaixo do percentil 3, informando também haver centralização fetal. Diante desse laudo, é correto afirmar que os achados encontrados na dopplerfluxometria em relação à resistência das artérias umbilical e cerebral média, respectivamente, serão:","options":{"A":"diminuída / diminuída","B":"diminuída / aumentada","C":"aumentada / diminuída","D":"aumentada / aumentada"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784766","ankiGuid":"C(?E.0Pb?["},{"id":"anki-obstetricia-vitalidade-fetal-b7ccb3028754f941","number":"0355h","sourceNumber":"0355h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Paciente G1 P0 A0, idade gestacional de 36 semanas, com diagnóstico de pré-eclâmpsia em uso de anti-hipertensivo. Comparece à maternidade por sentir que o seu bebê está se movimentando menos, sem outras queixas. Pressão arterial 130x80mmHg no momento da consulta. Ausência de contrações e colo uterino fechado. Ao realizar cardiotocografia, poder-se-à tranquilizar a paciente se os achados em traçado de 20 minutos forem linha de base com:","options":{"A":"125 batimentos por minuto, variabilidade de 15 batimentos por minuto e três aumentos da frequência cardíaca fetal de 15 batimentos cardíacos por minuto com duração de 15 segundos.","B":"130 batimentos por minuto, variabilidade de quatro batimentos por minuto e um aumento da frequência cardíaca fetal de 15 batimentos cardíacos por minuto com duração de 15 segundos.","C":"100 batimentos por minuto, variabilidade de dez batimentos por minuto e dois aumentos da frequência cardíaca fetal de 20 batimentos cardíacos por minuto com duração de 15 segundos.","D":"170 batimentos por minuto, variabilidade de 20 batimentos por minuto e três aumentos da frequência cardíaca fetal de dez batimentos cardíacos por minuto com duração de dez segundos."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784767","ankiGuid":"zzht40^poI"},{"id":"anki-obstetricia-vitalidade-fetal-4cf930f0c8990079","number":"0356h","sourceNumber":"0356h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O doppler de artéria cerebral média fetal apresentando índice de pulsatilidade (IP) baixo, sugerindo vasodilatação cerebral, indica que:","options":{"A":"há deslocamento do fluxo sanguíneo para o cérebro, e o achado se correlaciona com bons resultados em termos de bem-estar fetal durante o parto.","B":"não está havendo deslocamento do fluxo sanguíneo para o cérebro, e o achado se correlaciona com perda do bem-estar fetal durante o parto.","C":"não está havendo necessidade de deslocamento do fluxo sanguíneo para o cérebro, e o achado se correlaciona com bons resultados em termos de bemestar fetal durante o parto.","D":"há deslocamento do fluxo sanguíneo para o cérebro, e o achado se correlaciona com perda do bem-estar fetal durante o parto."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784768","ankiGuid":"KKu-e=.lPa"},{"id":"anki-obstetricia-vitalidade-fetal-2d48e7d2a2020a8a","number":"0357h","sourceNumber":"0357h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 35 semanas, acompanhada no ambulatório de pré-natal de alto risco por diabetes gestacional, apresenta exame de ultrassonografia com duração de 30 minutos, demonstrando feto único, apresentação cefálica, índice de líquido amniótico de 32 cm (maior bolsão vertical em 7,8 cm), peso estimado fetal no percentil 96, quatro movimentos fetais, um episódio de movimentos respiratórios rítmicos e um episódio de extensão e flexão das pernas.\nExame de cardiotocografia conforme a figura.\n\nAssinale a alternativa que contém o valor correto do perfil biofísico fetal clássico (Manning, 1980).","options":{"A":"06","B":"07","C":"08","D":"09","E":"10"},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-26044a7baa9fddfed94f2822215e4330d9f21b3f.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784769","ankiGuid":"FLkgZ_y<,_"},{"id":"anki-obstetricia-vitalidade-fetal-a34f3debc1c4b115","number":"0358h","sourceNumber":"0358h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A síndrome hipercinética consiste em alterações fetais que podem ser identificadas no doppler da artéria cerebral média fetal, encontrada nos casos de","options":{"A":"pré-eclâmpsia grave.","B":"síndrome HELLP.","C":"anemia fetal.","D":"cardiopatias congênitas."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784770","ankiGuid":"qYpF1q_0iI"},{"id":"anki-obstetricia-vitalidade-fetal-172cbb0130c65e4e","number":"0359h","sourceNumber":"0359h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 35 anos, G3P2vA0, idade gestacional de 38 semanas, comparece à maternidade referindo dores tipo contração e perda de líquido transvaginal. Teve diagnóstico de diabetes gestacional desde a terceira consulta de pré-natal e controlou com dieta. Ao exame: pressão arterial de 140x90mmHg, presença de contrações rítmicas, dilatação do colo uterino de 5cm, bolsa rota com líquido amniótico claro. Exame cardiotocográfico mostrou o seguinte traçado:\n\nQual o tipo de desaceleração apresentada (DIP) e em qual categoria de cardiotocografia intraparto esse traçado se enquadra?","options":{"A":"DIP 2; categoria 2.","B":"DIP 2; categoria 3.","C":"DIP 3; categoria 2.","D":"DIP 3; categoria 3."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-8707ca22fda82bd93ff01f8d05ac9873a5bb64b9.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784771","ankiGuid":"InHO;kob|O"},{"id":"anki-obstetricia-vitalidade-fetal-fc7a1e82971d901c","number":"0360h","sourceNumber":"0360h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante veio realizar ultrassonografia morfológica do primeiro trimestre e apresentou Dopplervelocimetria conforme a figura abaixo. Sobre que vaso é essa Dopplervelocimetria e o que indica essa alteração?","options":{"A":"Artéria umbilical. Sofrimento fetal","B":"Artéria cerebral média. Anemia fetal","C":"Artéria uterina. Risco aumentado para pré-eclâmpsia","D":"Artéria umbilical. Risco aumentado para restrição de crescimento fetal.","E":"Artéria uterina. Sofrimento fetal"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-e705ae0f399ee421965591e5de7c586b9d4d0729.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784772","ankiGuid":"fM10-STegB"},{"id":"anki-obstetricia-vitalidade-fetal-d70deb5bf8dd1008","number":"0361h","sourceNumber":"0361h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Adolescente, 15a, G1P0C0A0, comparece à consulta pré-natal, com idade gestacional 35 semanas, queixa-se de dor em hipocôndrio direito, náuseas e ganho de 1 kg em 1 semana. Exame físico: PA= 130x90 mmHg, Exame ginecológico: altura uterina de 32 cm, batimentos cardíacos fetais= 130 bpm. A CONDUTA É:","options":{"A":"Internação para cesárea de emergência.","B":"Internação, exames e avaliação de vitalidade fetal.","C":"Retorno em 7 dias com exames e avaliação vitalidade fetal.","D":"Orientar dieta, repouso, controle de pressão e retorno em pré-natal em 7 dias."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784773","ankiGuid":"o/9?_V%JhX"},{"id":"anki-obstetricia-vitalidade-fetal-eb39feb350b0c676","number":"0362h","sourceNumber":"0362h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Mulher, 42a, G3P2C2A0, idade gestacional 35 semanas comparece ao Pronto Socorro com queixa de redução de movimentos fetais. Refere múltiplos episódios de hipoglicemia embora mantenha padrão alimentar e a mesma dose de insulina. Antecedentes pessoais:diabetes e hipertensão gestacionais em uso de insulina NPH 30 unidades ao dia e metildopa 750mg/dia. Exame físico: PA= 110x80 mmHg. Fita urinária: proteína: negativa. ESSA INTERCORRÊNCIA PODE SER EXPLICADA POR:","options":{"A":"Desenvolvimento fisiológico da gestação.","B":"Pré-eclampsia sobreposta.","C":"Insuficiência placentária.","D":"Malformação fetal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784774","ankiGuid":"el$Bso%M50"},{"id":"anki-obstetricia-vitalidade-fetal-40b774bbe943f617","number":"0363h","sourceNumber":"0363h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Mulher, 25a, G2P1C0A0, idade gestacional de 41 semanas. Trabalho de parto induzido com ocitocina, queixando-se de muita dor. Toque vaginal: colo com 8 cm de dilatação, cefálico, plano -1 de De Lee, bolsa rota espontânea líquido claro com grumos grossos. Cardiotocografia:\n\nA CONDUTA NO MOMENTO É:","options":{"A":"Suspender ocitocina, analgesia e monitorização continua dos batimentos cardio fetais.","B":"Hidratação e cesárea de urgência sob raquianestesia.","C":"Manter ocitocina e parto fórceps Simpson com bloqueio pudendo bilateral.","D":"Aumentar ocitocina, analgesia e monitorização intermitente dos batimentos cardio fetais."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-e46be13f5793d90d5766f7f4b4d75cbd85c98f85.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784775","ankiGuid":"wQcY|^A2SL"},{"id":"anki-obstetricia-vitalidade-fetal-1758601245f1b22d","number":"0364h","sourceNumber":"0364h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Multípara, 38 anos de idade, hipertensa crônica e tabagista. A gestação, de alto risco, evolui com restrição de crescimento intrauterino. Atualmente, encontra-se na 34ª semana de gestação e é solicitada a realização de perfil biofísico fetal. Este exame é composto por 4 marcadores agudos e 1 crônico. O marcador crônico de sofrimento fetal por este método é representado por:","options":{"A":"Tônus fetal","B":"Volume de líquido amniótico","C":"Movimento corpóreo fetal","D":"Frequência cardíaca fetal"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784776","ankiGuid":"c8mbW4PpVP"},{"id":"anki-obstetricia-vitalidade-fetal-1b1d3b6655e578ad","number":"0365h","sourceNumber":"0365h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 37 semanas refere diminuição da movimentação fetal há um dia. O exame físico geral não mostra alterações e o exame obstétrico é compatível com a idade gestacional. Realiza-se cardiotocografia, em que a paciente registra 4 episódios de movimentação fetal, como mostrado na imagem abaixo.\n\nÉ correto afirmar que essa cardiotocografia","options":{"A":"é suspeita para início de hipóxia fetal, devendo-se induzir o parto.","B":"tem padrão tranquilizador e a paciente pode observar a movimentação fetal em casa.","C":"mostra início de trabalho de parto, devendo-se internar a paciente para monitoração do bem-estar fetal.","D":"mostra desacelerações tardias, sendo indicada resolução do parto nesse momento.","E":"mostra desacelerações variáveis, sendo indicada cesárea."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-e17eae5ffb7f7584955d14794f3184b85580de2b.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784777","ankiGuid":"EC,nX%*PR["},{"id":"anki-obstetricia-vitalidade-fetal-8cf980ec51ff7f97","number":"0366h","sourceNumber":"0366h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Para a interpretação do exame propedêutico Perfil Biofísico Fetal (PBF), deve-se considerar que","options":{"A":"nas gestações em que ocorreu placentação normal e invasão trofoblástica adequada, oleito das artérias uteroplacentárias funciona como um sistema de alta resistência, alta pressão e baixo fluxo.","B":"diante de uma injúria placentária e da hipoxemia crônica, pode ocorrer priorização dacirculação fetal para órgãos nobres, diminuição da perfusão sanguínea renal e pulmonar com consequente diminuição do líquido amniótico (LA).","C":"os principais parâmetros agudos avaliados no exame são os movimentos respiratóriosfetais, o líquido amniótico e o tônus fetal.","D":"na presença de insuficiência placentária decorrente de placentação inadequada,devido à segunda onda de invasão trofoblástica ausente ou incompleta, estabelece-se um regime de baixa resistência e fluxo elevado.","E":"de acordo com a \"\"Teoria da Hipóxia Gradual\"\", a sequência de anormalidades dasatividades biofísicas fetais relacionadas à hipóxia acontece na mesma ordem de aparecimento observada durante o período embrionário sendo, portanto, a frequência cardíaca fetal o último parâmetro a sofrer alterações."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784778","ankiGuid":"qK66MAo;s<"},{"id":"anki-obstetricia-vitalidade-fetal-b978da3b5a6d03da","number":"0367h","sourceNumber":"0367h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta, 22 anos, com 41 semanas, internou no início da fase ativa da dilatação com contrações moderadas e perda de tampão mucoso. Sem outras queixas. Pré-natal sem intercorrências. Há 30 minutos, queixou-se de muita dor e solicitou analgesia farmacológica. Foi submetida à bloqueio combinado raqui-peridural. Reavaliação após analgesia: sinais vitais maternos normais, atividade uterina de 4 contrações moderadas de 40 segundos em 10 minutos. A avaliação da vitalidade fetal está demonstrada na cardiotocografia exibida abaixo (figura). Toque: colo fino, centrado, dilatado 8 cm, feto cefálico, em zero de DeLee, bolsa íntegra.\n\nEscolha a melhor conduta na assistência a este trabalho de parto.","options":{"A":"Realizar ausculta intermitente da frequência cardíaca fetal.","B":"Promover corioamniorrexe artificial.","C":"Indicar resolução da gestação por cesárea.","D":"Instituir manobras de reanimação fetal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-94230ddb6c46c954eee4ada11c4afb5b88dceb3b.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784779","ankiGuid":"ea.ptg/MLW"},{"id":"anki-obstetricia-vitalidade-fetal-7772c14c0e6f5d99","number":"0368h","sourceNumber":"0368h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante, 32 anos de idade, secundigesta com uma cesárea anterior, 40 semanas e 2 dias de gravidez. Refere contrações irregulares e redução de movimentação fetal há 1 dia. Ao exame clínico, bom estado geral, corada, PA 120x70mmHg, altura uterina 30 cm, BCF presente rítmico. Toque vaginal com colo grosso, posterior, impérvio. Vitalidade fetal: tônus adequado, movimentação corpórea e respiratória presentes, índice de líquido amniótico de 4,2 cm. Cardiotocografia apresentada.\n\nQual é a conduta adequada neste momento?","options":{"A":"Controlar a vitalidade fetal em 2 dias.","B":"Preparar o colo com prostaglandina.","C":"Indicar parto de imediato por via alta.","D":"Realizar hidratação materna e reavaliação."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-f1badbd6cc1760522424c72dd0612cc5fb45a6fe.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784780","ankiGuid":"Bp?k#PF0~J"},{"id":"anki-obstetricia-vitalidade-fetal-205ee8f62a869ce9","number":"0369h","sourceNumber":"0369h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Considere o traçado da cardiotocografia abaixo. De acordo com o traçado, é correto inferir que há","options":{"A":"resposta vagal do feto à hipóxia pela diminuição do fluxo interviloso decorrente dacontração uterina.","B":"taquicardia fetal reativa à hipóxia causada pela contração uterina.","C":"ausência de acelerações transitórias por hipóxia fetal grave durante o trabalho de parto.","D":"bradicardia fetal por compressão do polo cefálico durante a contração uterina.","E":"bradicardia fetal por compressão localizada do cordão umbilical durante a contração uterina."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-3e4aee5165ed5a3bac109acb890f1012335aa804.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784781","ankiGuid":"BsSJ@SHO)g"},{"id":"anki-obstetricia-vitalidade-fetal-476300d795698013","number":"0370h","sourceNumber":"0370h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Em relação ao crescimento intrauterino restrito (CIUR), afirma-se: I. Há associação entre o CIUR e fatores de riscos cardiovasculares na vida adulta, como hipertensão arterial, dislipidemia e resistência à insulina. II. As principais causas do CIUR assimétrico são genéticas, infecções congênitas e uso de drogas, e a principal causa do tipo simétrico é a insuficiência placentária. III. Devido à placentação inadequada, eleva-se a resistência de perfusão e, consequentemente, o fluxo diastólico diminui à dopplervelocimetria das artérias umbilicais e precocemente ocorre alteração do ducto venoso fetal. Está/Estão correta(s) apenas a(s) afirmativa(s)","options":{"A":"I.","B":"III.","C":"I e II.","D":"II e III."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784782","ankiGuid":"b!BdMR8^q*"},{"id":"anki-obstetricia-vitalidade-fetal-e14881a96fc3ce56","number":"0371h","sourceNumber":"0371h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"A restrição de crescimento fetal (RCF) representa hoje uma patologia de relevância na prática clínica do obstetra. Sabe-se que atualmente o diagnóstico acurado, tal como o manejo criterioso desses fetos, é imprescindível para o desfecho perinatal adequado. Com relação à RCF, assinale a alternativa INCORRETA.","options":{"A":"A mortalidade do feto com restrição de crescimento é cerca de oito vezes maior quando comparada ao feto com peso adequado para a idade gestacional.","B":"O recém-nascido acometido pela RCF tem maior risco de insuficiência respiratória, hipoglicemia, hipocalemia, hipotermia e prejuízo no desenvolvimento neuropsicomotor.","C":"O estudo Doppler é um método que auxilia na distinção do feto pequeno para a idade gestacional constitucional daquele feto pequeno por insuficiência placentária.","D":"Estudos recentes indicam que o risco de resultado perinatal adverso em casos de RCF tardia pode ser melhor avaliado pelo Doppler cerebral, visto que o Doppler da artéria umbilical pode não se modificar.","E":"Em casos de insuficiência placentária prolongada, evoluindo com vasoconstrição periférica fetal intensa, observa-se a deterioração da função cardíaca que pode ser avaliada pelo Doppler do ducto arterioso."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784783","ankiGuid":"MX%nn<3^tk"},{"id":"anki-obstetricia-vitalidade-fetal-3ed281cbb025858d","number":"0372h","sourceNumber":"0372h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O exame ultrassonográfico de eleição para avaliar insuficiência placentária em casos com restrição de crescimento intra-uterino é:","options":{"A":"Medida do volume de líquido amniótico.","B":"Doppler de artérias uterinas.","C":"Doppler de artéria cerebral média.","D":"Doppler de artéria umbilical."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784784","ankiGuid":"Ef{OU)lE|d"},{"id":"anki-obstetricia-vitalidade-fetal-0f4508261020fd7a","number":"0373h","sourceNumber":"0373h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Na síndrome anemia-policitemia em gestação dupla, o método propedêutico a ser usado para estudo fetal é","options":{"A":"a diferença de peso entre os fetos acima de 20%.","B":"a presença de polihidrâmnio em 1 feto e oligoâmnio no outro.","C":"o estudo dopplervelocimétrico da artéria cerebral média de ambos os fetos.","D":"a restrição de crescimento secundária de um dos fetos.","E":"a presença de desacelerações variáveis à cardiotocografia em um dos fetos."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784785","ankiGuid":"qv-D#y=@:p"},{"id":"anki-obstetricia-vitalidade-fetal-67ed395c5839316a","number":"0374h","sourceNumber":"0374h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Considerando a avaliação do bem-estar fetal, é correto afirmar:","options":{"A":"Na avaliação do perfil biofísico fetal, é possível a presença de oligo-hidrâmnio, pela avaliação do índice de líquido amniótico, porém com nota máxima (nota 2) para essa variável (líquido amniótico).","B":"Durante a cardiotocografia, os valores considerados normais para a frequência cardíaca fetal são de 120 a 160 batimentos por minuto (bpm).","C":"Em uma gravidez a termo, é considerada aceleração transitória um aumento da frequência cardíaca fetal de pelo menos dez batimentos com duração de pelo menos dez segundos.","D":"A desaceleração intraparto tardia ou DIP II está relacionada à compressão do polo cefálico fetal, determinando reflexo vagal com consequente diminuição da frequência cardíaca fetal."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784786","ankiGuid":"ND7phD$wk}"},{"id":"anki-obstetricia-vitalidade-fetal-5dd3ee532230de9e","number":"0375h","sourceNumber":"0375h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Durante o trabalho de parto espontâneo de uma gestação com 40 semanas e dois dias e complicada por hipotiroidismo materno, o traçado cardiotocográfico foi obtido e está apresentado a seguir. Interprete o registro gráfico nas regiões marcadas como A, B, C e D. Faça a correspondência dessas regiões na coluna 1 com os achados descritos na coluna 2 e assinale a sequência CORRETA:\n\nCOLUNA 1\nRegião A;\nRegião B;\nRegião C;\nRegião D.\n\nCOLUNA 2\n( ) Aceleração transitória da frequência cardíaca fetal;\n( ) Contrações uterinas;\n( ) Movimento fetal;\n( ) Linha de base da frequência cardíaca fetal;","options":{"A":"A, D, B, C","B":"B, D, C, A","C":"C, A, B, D","D":"D, B, A, C"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-17f9093f0f5838bc1aab2102e6e8a21007c246b3.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784787","ankiGuid":"zc];b&cLX|"},{"id":"anki-obstetricia-vitalidade-fetal-dc59f279be78dedb","number":"0376h","sourceNumber":"0376h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"No perfil hemodinâmico fetal, a circulação placentária é avaliada pelo doppler de:","options":{"A":"artéria cerebral média.","B":"ducto venoso.","C":"artéria uterina.","D":"artéria umbilical."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784788","ankiGuid":"ospct$2rc$"},{"id":"anki-obstetricia-vitalidade-fetal-07572d62854a5db3","number":"0377h","sourceNumber":"0377h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Uma gestante com 35 semanas de idade gestacional dá entrada no pronto atendimento obstétrico com queixa de cefaleia intensa e \"visão embaçada\". Notou ainda que vem urinando pouco ao longo dos últimos dois dias. Ao exame, não há dinâmica uterina, BCF = 90 bpm, e o colo é grosso, pérvio para uma polpa digital ao toque vaginal. Apresenta PA = 160 mmHg x 110 mmHg em duas aferições, frequência cardíaca = 102 bpm, frequência respiratória = 20 ipm e SatO₂ = 97% em ar ambiente. Amostra isolada de urina com 3+ de proteinúria. Considerando esse caso clínico e os conhecimentos médicos correlatos, julgue o item a seguir. O caso deve ser classificado como pré-eclâmpsia grave, devendo-se iniciar indução do parto vaginal com misoprostol e avaliação rigorosa de bem-estar fetal.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784789","ankiGuid":"P$H-:h4EB-"},{"id":"anki-obstetricia-vitalidade-fetal-f4301f55d4be79a2","number":"0378h","sourceNumber":"0378h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Uma paciente com idade gestacional de trinta semanas apresenta quadro de restrição de crescimento fetal e diástole reversa na artéria umbilical, conforme identificado por doppler. Nessa situação, a conduta recomendada pelo protocolo da Secretaria de Saúde do Distrito Federal é a administração de sulfato de magnésio à mãe, visando à neuroproteção fetal, com posterior interrupção do parto via alta.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784790","ankiGuid":"ljx_&&zJFS"},{"id":"anki-obstetricia-vitalidade-fetal-1753832e6c733344","number":"0379h","sourceNumber":"0379h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Parturiente de 39 semanas e 4 dias, primigesta, chega ao pronto-socorro com queixa de dor em baixo ventre, Nega patologias obstétricas ou clínicas. Ao exame físico, apresenta-se corada e hidratada, PA: 12 x 80mmHg, FC 80bpm. Altura uterina 34 cm, dinâmica uterina 3 contrações fortes em 10 minutos, ao toque vaginal colo com dilatação de 4cm, médio, -1 De Lee. Observe a imagem.\n\nBaseando-se na cardiotocografia apresentada, qual é a classificação do traçado e a conduta correta?","options":{"A":"Categoria III, esforços imediatos para reverter o padrão ou resolução parto.","B":"Categoria 0, sem conduta específica, controle habitual do trabalho de parto .","C":"Categoria II, oxigenioterapia e cardiotocografia.","D":"Categoria I, aguardar resolução parto.","E":"Categoria II, aguardar a resolução do parto."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-e75fc02001d905577cad6b61dd469ac8b0dbf4f0.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784791","ankiGuid":"fZr]iilw!)"},{"id":"anki-obstetricia-vitalidade-fetal-3025c88773ddfe5b","number":"0380h","sourceNumber":"0380h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Mulher, 25 anos, G1P0, 34 semanas de gestação, sem intercorrências vai à consulta pré-natal. Exames de rotina normais. Ganho de peso adequado. Ao exame: normotensa, altura uterina 25 cm; batimentos cardiofetais de 128 bpm; ausência de contrações uterinas. Qual deverá ser a conduta inicial?","options":{"A":"Prescrever corticoterapia.","B":"Carditotocografia imediata.","C":"Dopplervelocimetria.","D":"Perfil Biofísico Fetal.","E":"Parto cesareana por sofrimento fetal"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784792","ankiGuid":"uOM}Ok#<or"},{"id":"anki-obstetricia-vitalidade-fetal-173bfdc767a1919b","number":"0381h","sourceNumber":"0381h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Uma gestante secundigesta com parto normal anterior realizou pré-natal, detectando, na rotina de exames iniciais, uma tipagem sanguínea B negativo, Du negativo. Seu obstetra verificou a tipagem sanguínea do pai, que é A positivo. Assim, solicitou Coombs indireto no sangue materno, que se demonstrou positivo para anti-D, motivo que lhe fez manter solicitação mensal desse exame. Na 28.ª semana de gravidez, o resultado do Coombs era de 1:32. Foi, então, avaliado, por meio de USG Doppler, o pico sistólico da artéria cerebral média e o resultado foi de 1,1 múltiplo de mediana. Nesse caso hipotético, a próxima etapa será","options":{"A":"resolver a gestação.","B":"solicitar Coombs indireto em quinze dias.","C":"realizar avaliação semanal do pico sistólico da artéria cerebral média.","D":"realizar cordocentese para verificar a necessidade de transfusão intrauterina.","E":"administrar imunoglobulina anti-D."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784793","ankiGuid":"o${d9wdc2m"},{"id":"anki-obstetricia-vitalidade-fetal-5a13dfe4df321fac","number":"0382h","sourceNumber":"0382h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O método mais utilizado para avaliação de vitalidade fetal intraparto é:","options":{"A":"Dopplerfluxometria.","B":"Cardiotocografia.","C":"Ultrassonografia.","D":"Fetoscopia.","E":"Dosagem de pH."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784794","ankiGuid":"MjucoYzC]x"},{"id":"anki-obstetricia-vitalidade-fetal-10539b856a5048eb","number":"0383h","sourceNumber":"0383h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Com relação ao perfil biofísico fetal: I - O índice 0 (zero) corresponde ao óbito fetal; II - A cardiotocografia é o primeiro componente a se alterar; III - A glicemia materna não exerce influência sobre as atividades biofísicas fetais; IV - A oligoidrâmnia indica risco para hipoxemia fetal crônica. Está correto apenas o contido em:","options":{"A":"I, II e III","B":"I e III","C":"II e IV","D":"III e IV","E":"IV"},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784795","ankiGuid":"bnz#}uaBQ["},{"id":"anki-obstetricia-vitalidade-fetal-c37912f40d46b125","number":"0384h","sourceNumber":"0384h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta, 28 anos de idade, encontra-se na fase ativa do trabalho de parto, apresenta cardiotocografia conforme a figura abaixo. A dilatação cervical é de 6 cm, bolsa rota, líquido claro. Nesse caso, o tipo de desacelerações da frequênciacardíaca fetal detectada e o próximo passo para o melhor cuidado, respectivamente, são:","options":{"A":"variáveis; mudança de decúbito","B":"tardias; expansãovolêmica","C":"precoces; amnioinfusão","D":"precoces; cesárea","E":"Nenhuma das anteriores"},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-30e8aee8ec842ab7c12693c1b60976b13369d2c8.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784796","ankiGuid":"z,Jn#gb2{]"},{"id":"anki-obstetricia-vitalidade-fetal-75da96c60d0fd551","number":"0385h","sourceNumber":"0385h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O método mais utilizado para a avaliação da vitalidade fetal intra parto é:","options":{"A":"Dopplerfluxometria","B":"Cardiotocografia","C":"Ultrassonografia","D":"Perfil Biofísico-fetal"},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784797","ankiGuid":"s|Ai[VzXsV"},{"id":"anki-obstetricia-vitalidade-fetal-1aeded48b169203c","number":"0386h","sourceNumber":"0386h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"O laudo de um ultrassom obstétrico realizado com 26 semanas de gestação demonstra presença de incisura protodiastólica bilateral de artérias uterinas. Isso pode significar:","options":{"A":"Risco aumentado de desenvolver Diabete Gestacional.","B":"Risco aumentado de Restrição de crescimento fetal.","C":"Centralização fetal neste momento.","D":"Provável desenvolvimento de macrossomia fetal."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784798","ankiGuid":"O#bt.ReD$C"},{"id":"anki-obstetricia-vitalidade-fetal-cc449330d5df97dd","number":"0387h","sourceNumber":"0387h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Em relação ao Doppler de artéria umbilical, assinale a alternativa INCORRETA:","options":{"A":"O aumento na relação S/D está associado a aumento da resistência vascular no leito placentário.","B":"A pré-eclampsia e a restrição de crescimento fetal têm forte relação com alterações do Doppler de artéria umbilical.","C":"A diástole zero representa comprometimento fetal severo.","D":"Não tem valor preditivo em caso de gestação gemelar."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784799","ankiGuid":"vVX^_)#@I&"},{"id":"anki-obstetricia-vitalidade-fetal-221e5c47023d64fe","number":"0388h","sourceNumber":"0388h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante com 29 semanas é diagnosticada com pré-eclâmpsia grave, restrição de crescimento fetal, insuficiência placentária grave e centralização fetal, com perfil biofísico fetal10. Para predição de acidemia fetal utilizamos a dopplerfluxometria do ducto venoso. Identifique o ducto venoso no esquema de circulação fetal demonstrado a seguir.","options":{"A":"(VER IMAGEM).","B":"(VER IMAGEM).","C":"(VER IMAGEM).","D":"(VER IMAGEM)."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-a63dbf008fbb4eb48b7a1c670019dd0d81102990.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784800","ankiGuid":"I,N8dRgViQ"},{"id":"anki-obstetricia-vitalidade-fetal-d3c09e7d781f60bc","number":"0389h","sourceNumber":"0389h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante com 29 semanas é diagnosticada com pré-eclâmpsia grave, restrição de crescimento fetal, insuficiência placentária grave e centralização fetal, com perfil biofísico fetal10. Qual dos parâmetros do perfil biofísico fetal tem maior dependência da oxigenação do sistema nervoso central?","options":{"A":"Movimento respiratório.","B":"Tônus corpóreo fetal.","C":"Movimento corpóreo.","D":"Indice de líquido amniótico."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784801","ankiGuid":"KFOtPcITkK"},{"id":"anki-obstetricia-vitalidade-fetal-b28e2d9089d8608d","number":"0390h","sourceNumber":"0390h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 32 semanas vem ao PS com queixa de diminuição da movimentação fetal. Até o momento, pré-natal de risco habitual. Foi solicitado ultrassonografia obstétrica com dopplervelocimetria, com a seguinte imagem em questão:\n\nQual a conduta?","options":{"A":"Amnioinfusão para aumento do líquido amniótico e reavaliação em 12 horas.","B":"Reavaliação com perfil biofísico fetal em 24 horas.","C":"Cardiotocografia a cada 6 horas.","D":"Corticoterapia e resolução da gestação."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-ef51120dc4d26d61559308544001c00258251137.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784802","ankiGuid":"z0/i;,wuM^"},{"id":"anki-obstetricia-vitalidade-fetal-fe91731178a55519","number":"0391h","sourceNumber":"0391h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Em pacientes com pré-eclampsia grave, ao se instalar a hipoxemia fetal, os primeiros movimentos fetais que desaparecem são","options":{"A":"os de mãos.","B":"os do tronco.","C":"os respiratórios.","D":"os dos membros."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784803","ankiGuid":"ON:V;D`8H`"},{"id":"anki-obstetricia-vitalidade-fetal-f1d5a946ca6d2ad1","number":"0392h","sourceNumber":"0392h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Na assistência pré-natal nas gestações de baixo risco, quando é recomendável indicar métodos biofísicos de análise da vitalidade fetal?","options":{"A":"Sempre que a gestante referir diminuição da movimentação fetal, independentemente da idade gestacional.","B":"Na gestação prolongada.","C":"Em qualquer momento durante o pré-natal.","D":"Rotineiramente, após 37 semanas de gestação."},"answer":"B","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784804","ankiGuid":"m~5^EDmj$9"},{"id":"anki-obstetricia-vitalidade-fetal-bda3320354a5ee71","number":"0393h","sourceNumber":"0393h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Jovem de 21 anos iniciou acompanhamento pré-natal em unidade de saúde da família na primeira semana de dezembro de 2017, tendo informado DUM em 28/08/2017. A gestação evoluiu sem intercorrências até maior de 2018, quando a gestante viajou para o interior do estado do Rio de Janeiro e interrompeu seu pré-natal. Ao retornar em 28/06/2018, procurou a emergência da maternidade para atualizar seu acompanhamento. No momento do atendimento, a paciente se encontrava sem queixas, com sinais vitais normais e rotina pré-natal de primeiro trimestre sem alterações. As ultrassonografias realizadas durante a gravidez, apresentaram os seguintes resultados: 18/11/2017 = IG de 10 semanas; 20/02/2018 = IG de 22 semanas; 29/05/2018 = IG de 35 semanas e 1 dia. Durante o atendimento, foi realizada cardiotocografia (CTG) que apresentou o seguinte traçado.\n\nA análise do traçado da cardiotocografia sugere:","options":{"A":"boa vitalidade fetal","B":"manobra vagal","C":"acidose fetal","D":"oligodramnia"},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-a87b409a02cc0f6f30fa4872fd6b00ee1b87ceb3.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784805","ankiGuid":"k_F3J#`<-k"},{"id":"anki-obstetricia-vitalidade-fetal-be8e7dd12982dbb9","number":"0394h","sourceNumber":"0394h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Quando se analisa o resultado de um Perfil Biofísico Fetal (PBF), há a obrigatoriedade de se saber a teoria da hipóxia gradual. Dessa forma, a sequência cronológica da deterioração fetal intrauterina é a ausência de:","options":{"A":"Movimento corpóreo, tônus, movimento respiratório, reatividade cardíaca.","B":"Movimento corpóreo, tônus, reatividade cardíaca, movimento respiratório.","C":"Reatividade cardíaca, movimento respiratório, movimento corpóreo, tônus.","D":"Reatividade cardíaca, movimento corpóreo, movimento respiratório, tônus.","E":"Tônus, movimento corpóreo, movimento respiratório, reatividade cardíaca."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784806","ankiGuid":"g>%LKA&l+$"},{"id":"anki-obstetricia-vitalidade-fetal-b85bc39649f99c4f","number":"0395h","sourceNumber":"0395h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Com relação à Restrição de Crescimento Intrauterino (RCIU), assinale a alterantiva correta.","options":{"A":"A restrição de crescimento intrauterino tem como principal causa a infecção por citomegalovírus, visto que esse patógeno está associado à aplasia medular fetal.","B":"A produção deficiente de insulina materna tem sido demonstrada como fator intrínseco à gênese da RCIU.","C":"A restrição do crescimento intrauterino pode ser tratada pela utilização de anti- hipertensivos de ação central ou pela utilização de betabloqueadores.","D":"No caso de diástole zero da artéria umbilical, o próximo vaso a ser avaliado é a artéria cerebral média.","E":"A dopplervelocimetria permite a diferenciação do feto pequeno por insuficiência placentária do feto pequeno constitucional."},"answer":"E","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784807","ankiGuid":"csE/q.vr)A"},{"id":"anki-obstetricia-vitalidade-fetal-21aecdd24a985004","number":"0396h","sourceNumber":"0396h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Na admissão de uma primigesta de 38 semanas e dois dias de gravidez, em trabalho de parto com três contrações de quarenta segundos em dez minutos, com toque vaginal revelando colo pérvio para 5 cm, apresentação cefálica e bolsa íntegra, foi realizada cardiotocografia com os seguintes parâmetros: linha de base de 126 bpm (batimentos por minuto); variabilidade de 8 bpm; e acelerações e desacelerações ausentes. Considerando essa situação hipotética, assinale a alternativa correta.","options":{"A":"Trata-se de um traçado categoria I da OMS, devendo-se acompanhar o trabalho de parto.","B":"A ausência de acelerações indica sofrimento fetal agudo, devendo-se resolver a gestação.","C":"A variabilidade é reduzida, o que pode estar associado a sono fetal, devendo-se realizar estímulo sonoro.","D":"Trata-se de uma cardiotocografia de categoria II da OMS, devendo-se adotar manobras de ressuscitação fetal e posterior reavaliação.","E":"Está indicada, nesse caso, a inibição do trabalho de parto, preferencialmente com atosiban."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784808","ankiGuid":"s+hS=Z[`t*"},{"id":"anki-obstetricia-vitalidade-fetal-e869b9de4fb452f8","number":"0397h","sourceNumber":"0397h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Tercigesta, 28 anos de idade, com 19 semanas de idade gestacional, apresentando exame de coombs indireto com título=1:32 tipagem sanguínea=O negativo. Considerando o diagnóstico diante deste quadro assinale a melhor opção para o controle da anemia fetal.","options":{"A":"Medida do pico de velocidade sistólica na dopplervelocimetria da artéria cerebral média.","B":"Dosagem de anticorpos anti-Rh no capilar fetal.","C":"Medida da circunferência cefálica na ultrassonografia obstétrica.","D":"Medida da translucência nucal na ultrassonografia.","E":"Hemograma materno."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784809","ankiGuid":"sy^#:/:WHg"},{"id":"anki-obstetricia-vitalidade-fetal-b39abcf8b9fd80aa","number":"0398h","sourceNumber":"0398h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante de 38 anos, G1P0A0, sem comorbidades, com pré-natal sem intecorrências e com 37 semanas e seis dias de gravidez. Ultrassonografia realizada hoje revela peso fetal estimado e cincunferência abdominal fetal no percentil 3. Perfil biofísico fetal 6/8 (perdeu em movimento respiratório). Exame clínico e obstétrico sem alterações. Toque vaginal com colo uterino apagado 50%, centralizado e com 2cm de dilatação. Polo cefálico no plano - 2 de De Lee. Bolsa formada. Cardiotocografia fetal realizada no momento do atendimento com padrão tranquilizador. Diante desse quadro, assinale a MELHOR conduta.","options":{"A":"Internar a paciente para administração de corticoterapia.","B":"Internar a paciente para cesariana eletiva.","C":"Internar a paciente para indução do parto.","D":"Internar a paciente para repetir ultrassonografia com Doppler fetal."},"answer":"C","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":[],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784810","ankiGuid":"h::g_f/@,0"},{"id":"anki-obstetricia-vitalidade-fetal-95f7cf452cfb3828","number":"0399h","sourceNumber":"0399h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Gestante no curso das 31 semanas, com diagnóstico prévio de trombofilia, em uso de anticoagulação profilática e ácido acetilsalicílico. Realizou avaliação ultrassonográfica que evidenciou feto com peso estimado abaixo do percentil 10 e Doppler de artéria umbilical com o sonograma apresentado na figura abaixo.\n\nQual a melhor conduta?","options":{"A":"Dopplervelocimetria obstétrica a cada 2 a 3 dias.","B":"Dopplervelocimetria obstétrica semanal.","C":"Perfil biofísico fetal diário.","D":"Indicar o parto."},"answer":"A","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-0f3e1858c34dece6c6c7f36d2421493ef4f4d560.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784811","ankiGuid":"xAp%D~[)lj"},{"id":"anki-obstetricia-vitalidade-fetal-6a4ae3de68a061cf","number":"03100h","sourceNumber":"03100h","collectionBlock":"anki:obstetricia-vitalidade-fetal","collectionLabel":"Anki · Vitalidade Fetal","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"Vitalidade Fetal","subtopic":"","stem":"Primigesta, 28 anos de idade, encontra-se na fase ativa do trabalho de parto, apresenta cardiotocografia conforme a figura. A dilatação cervical é de 5 cm, bolsa rota, líquido claro.\n\nNesse caso, o tipo de desacelerações da frequência cardíaca fetal e o próximo passo para o melhor cuidado, respectivamente, são:","options":{"A":"Precoces; amnioinfusão.","B":"Tardias; cesárea.","C":"Variáveis; cesárea.","D":"Variáveis; mudança de decúbito.","E":"Tardias, expansão volêmica."},"answer":"D","source":"Z - Residência médica (Questões + Osler)__Residência Médica__Grupo 1 (Segunda-feira)__03 - Obstetrícia.apkg","sourceLabel":"Anki · Vitalidade Fetal","images":["question_bank/media/obstetricia-vitalidade-fetal/paste-5eea1ffecd67d4ed34cb51207c2ed6fe62e0f838.png"],"optionImages":{},"commentImages":[],"comment":"","tags":["Ginecologia e Obstetrícia","Vitalidade Fetal","Anki"],"ankiNoteId":"1776637784812","ankiGuid":"ko[[N)+)f("}]};
